import re
path = "src/click/core.py"
with open(path) as f:
    content = f.read()

old = '''    def make_metavar(self, ctx: Context) -> str:
        if self.metavar is not None:
            return self.metavar
        var = self.type.get_metavar(param=self, ctx=ctx)
        if not var:
            var = self.name.upper()
        if self.deprecated:
            var += "!"
        if not self.required:
            var = f"[{var}]"
        if self.nargs != 1:
            var += "..."
        return var'''

new = '''    def make_metavar(self, ctx: Context) -> str:
        if self.metavar is not None:
            return self.metavar
        var = self.type.get_metavar(param=self, ctx=ctx)
        if not var:
            var = self.name.upper()
        if self.deprecated:
            var += "!"
        if not self.required and not (
            (var.startswith("[") and var.endswith("]"))
            or (var.startswith("{") and var.endswith("}"))
        ):
            var = f"[{var}]"
        if self.nargs != 1:
            var += "..."
        return var'''

assert old in content
content = content.replace(old, new)
with open(path, "w") as f:
    f.write(content)
EOF
